import {campaignRules} from './campaign-rules.js?v=203';
import {COUNTRY} from './data.js?v=203';
import {icon,button,esc,flag,formatScore} from './ui.js?v=203';
import {campaignSummary,prestigeChart,contributionBreakdown} from './campaign-stats.js?v=203';
import {clockMarkup} from './campaign-clock.js?v=203';
export function endingScreen(s,options={}){
 const win=s.ended==='victory',factions=Object.values(s.factions).sort((a,b)=>b.score-a.score),best=factions.filter(f=>f.score===factions[0].score),max=Math.max(1,...factions.map(f=>f.score)),cells=[0,1,2].filter(cell=>s.suspects.filter(t=>t.cell===cell).every(t=>t.arrested)).length;
 const title=win?'Fracture est démantelée.':'Le monde a basculé.',verdict=win?(best.length>1?'VICTOIRE NATIONALE PARTAGÉE':'PAYS VAINQUEUR'):'CONTRIBUTIONS DES PAYS',reason=win?'L’Architecte est arrêté et au moins deux cellules sont démantelées. Victoire collective.':s.crisis>=100?'Crise mondiale à 100 : défaite collective. Aucun pays vainqueur.':`Le délai de ${campaignRules(s).maxTurns} tours est écoulé : défaite collective. Aucun pays vainqueur.`;
 return `<main class="ending-page"><section class="ending-ceremony ${win?'is-victory':'is-defeat'}" aria-labelledby="ending-title"><div class="ending-rays" aria-hidden="true"></div><div class="ending-particles" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i style="--i:${i};--x:${(i*37)%100}%;--delay:${(i%7)*.13}s"></i>`).join('')}</div><header class="ending-verdict"><span class="eyebrow">SIGMA 2040 · FIN DE CAMPAGNE · TOUR ${s.turn}</span><div class="ending-emblem" aria-hidden="true">${icon(win?'shield':'world')}</div><p class="ending-outcome">${win?'VICTOIRE COLLECTIVE':'DÉFAITE COLLECTIVE'}</p><h1 id="ending-title" tabindex="-1">${title}</h1><p>${reason}</p>${win?`<div class="ending-winners"><span>${verdict}</span><strong>${best.map(f=>`${flag(f.id)} ${esc(COUNTRY[f.id].name)}`).join('<span class="winner-divider"> & </span>')}</strong></div>`:''}</header><div class="ending-results"><section class="ending-ranking" aria-label="Prestige final par pays"><span class="eyebrow">${verdict} · PRESTIGE FINAL</span>${factions.map((f,i)=>`<article class="ending-score-row ${win&&best.includes(f)?'is-winner':''}" style="--rank:${i}"><span class="ending-rank">${1+factions.filter(other=>other.score>f.score).length}</span>${flag(f.id)}<div class="ending-country"><strong>${esc(COUNTRY[f.id].name)}${f.id===s.player?' <small>VOUS</small>':''}</strong><span class="ending-protection-points">Protection : ${formatScore(contributionBreakdown(s,f.id).protection)} pts · ${contributionBreakdown(s,f.id).defended} attaque(s) déjouée(s)</span><div class="ending-score-track"><i style="--score-width:${Math.max(0,f.score/max*100)}%"></i></div></div><strong class="ending-score" aria-label="${formatScore(f.score)} points"><span data-ending-score="${f.score}" aria-hidden="true">${formatScore(f.score)}</span><small>PTS</small></strong></article>`).join('')}</section><div class="ending-progression">${prestigeChart(s,factions)}</div></div><div class="ending-actions">${button('Explorer le bilan','ending-report','primary')}${button('Derniers événements','reveal-replay')}${button('Menu principal','main-menu')}</div></section><header class="ending-header"><div><span class="eyebrow">BILAN / ARCHIVES DE CAMPAGNE</span><h2>Bilan des opérations</h2></div><div class="ending-actions">${button('Archives','nav','','data-id="journal"')}${button('Nouvelle campagne','new','primary')}</div></header><div class="ending-overview">${clockMarkup(s)}<div><span>ARRESTATIONS</span><strong>${s.suspects.filter(t=>t.arrested).length} / ${s.suspects.length}</strong></div><div><span>CELLULES DÉMANTELÉES</span><strong>${cells} / 3</strong></div><div><span>CRISE MONDIALE</span><strong>${s.crisis} / 100</strong></div></div><div id="campaign-report" tabindex="-1">${campaignSummary(s,options)}</div></main>`;
}
export function mountEnding(root,{reducedMotion=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches||false}={}){
 const counters=[...root.querySelectorAll('[data-ending-score]')];let frame=0,start=null;
 root.querySelector('#ending-title')?.focus({preventScroll:true});
 if(reducedMotion||globalThis.document?.documentElement.classList.contains('reduce-feedback'))return ()=>{};
 const tick=now=>{start??=now;const progress=Math.min(1,(now-start)/1800),eased=1-(1-progress)**3;for(const el of counters)el.textContent=formatScore(Number(el.dataset.endingScore)*eased);if(progress<1)frame=requestAnimationFrame(tick);};
 for(const el of counters)el.textContent='0';frame=requestAnimationFrame(tick);
 return ()=>cancelAnimationFrame(frame);
}
